"""Invoice total calculation using decimal arithmetic."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_MISSING = object()


def _as_decimal(value, field):
    if value is _MISSING:
        raise ValueError(f"missing field: {field}")
    if not isinstance(value, str):
        raise ValueError(f"field {field!r} must be a string")
    try:
        return Decimal(value)
    except InvalidOperation:
        raise ValueError(f"field {field!r} is not a valid decimal: {value!r}") from None


def _reject_negative(value, field):
    if value < 0:
        raise ValueError(f"field {field!r} must not be negative: {value}")


def _is_finite(value):
    return value.is_finite()


def _round_half_up(value):
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _format_amount(value):
    return f"{value:.2f}"


def invoice_total(lines, discount_percent="0"):
    """Compute the net, tax, and total for a list of invoice lines.

    Each line is a dictionary with ``quantity``, ``unit_price``, and
    ``vat_percent`` decimal string fields. The discount is applied to each
    line's net amount before tax is calculated.

    Args:
        lines (list[dict]): Invoice lines.
        discount_percent (str): Discount percentage, between 0 and 100.

    Returns:
        dict: ``{"net": ..., "tax": ..., "total": ...}`` with two-decimal
            strings.

    Raises:
        ValueError: For invalid inputs.
    """
    discount = _as_decimal(discount_percent, "discount_percent")
    if discount < 0:
        raise ValueError(f"discount_percent must not be negative: {discount_percent}")
    if discount > 100:
        raise ValueError(f"discount_percent must be at most 100: {discount_percent}")

    net = Decimal("0")
    tax = Decimal("0")

    for line in lines:
        if not isinstance(line, dict):
            raise ValueError("each line must be a dictionary")

        quantity = _as_decimal(line["quantity"], "quantity")
        unit_price = _as_decimal(line["unit_price"], "unit_price")
        vat_percent = _as_decimal(line["vat_percent"], "vat_percent")

        for field in (quantity, unit_price, vat_percent):
            _reject_negative(field, field.name)
            if not _is_finite(field):
                raise ValueError(f"field {field.name!r} must be finite: {field}")

        line_net = quantity * unit_price
        line_net = line_net * (Decimal("1") - discount / Decimal("100"))
        line_net = _round_half_up(line_net)

        line_tax = _round_half_up(vat_percent * line_net / Decimal("100"))

        net += line_net
        tax += line_tax

    return {
        "net": _format_amount(net),
        "tax": _format_amount(tax),
        "total": _format_amount(net + tax),
    }
