def order_tasks(tasks):
    """Return task ids in dependency-first topological order.

    At each step the ready task that appeared earliest in the original
    input is chosen, including tasks that just became ready. Duplicate
    dependencies count as a single edge. Raises ValueError for duplicate
    ids, unknown dependencies, self dependencies, or cycles.
    """
    if not isinstance(tasks, list):
        raise TypeError("tasks must be a list")

    # Validate and build the graph without mutating the input.
    ids = {}
    edges = {}
    for index, task in enumerate(tasks):
        if not isinstance(task, dict):
            raise TypeError("each task must be a dictionary")
        task_id = task.get("id")
        if task_id is None:
            raise ValueError("each task must have an 'id'")
        if task_id in ids:
            raise ValueError(f"duplicate task id: {task_id!r}")
        ids[task_id] = index
        deps = task.get("depends_on", [])
        if not isinstance(deps, list):
            raise TypeError(f"depends_on for {task_id!r} must be a list")
        for dep in deps:
            if dep == task_id:
                raise ValueError(f"self dependency for task {task_id!r}")
            if dep not in ids:
                raise ValueError(f"unknown dependency {dep!r} for task {task_id!r}")
            edge = edges.setdefault(task_id, set())
            edge.add(dep)
        edges[task_id] = edge

    remaining = set(ids)
    ordered = []
    while remaining:
        # Pick the ready task with the earliest position in the input.
        ready = [task_id for task_id in ids if task_id not in remaining]
        if not ready:
            # Every task has at least one unfinished predecessor: cycle.
            raise ValueError("dependency cycle detected")
        chosen = min(ready, key=ids.get)
        ordered.append(chosen)
        remaining.discard(chosen)
        for successor in edges.get(chosen, ()):
            if successor in remaining:
                remaining.discard(successor)

    return ordered

