  createAsyncCache: function (load, ttlMs, now) {
    if (typeof now !== 'function') {
      now = Date.now;
    }

    var cache = Object.create(null);

    function get(key) {
      var entry = cache[key];

      if (entry && entry.state === 'fulfilled') {
        if (now() < entry.expiresAt) {
          return Promise.resolve(entry.value);
        }
      }

      if (entry && entry.state === 'pending') {
        return entry.promise;
      }

      var loadPromise = load(key);
      var state = 'pending';
      var value = undefined;
      var expiresAt = 0;

      var promise = new Promise(function (resolve, reject) {
        loadPromise.then(function (val) {
          if (state !== 'pending') {
            return;
          }

          state = 'fulfilled';
          value = val;
          expiresAt = now() + ttlMs;

          cache[key] = {
            state: state,
            value: value,
            expiresAt: expiresAt
          };

          resolve(value);
        }, function (err) {
          if (state !== 'pending') {
            return;
          }

          state = 'rejected';
          cache[key] = {
            state: state
          };

          reject(err);
        });
      });

      cache[key] = {
        state: state,
        promise: promise
      };

      return promise;
    }

    function invalidate(key) {
      delete cache[key];
    }

    return {
      get: get,
      invalidate: invalidate
    };
  }
};
